 1	/**
 2	 * El dialecto de base de datos y la apertura de una conexión por URL, para
 3	 * cualquier store de thyrox. `Bun.SQL` da la misma API a varios motores; lo
 4	 * que cambia entre ellos —los tipos que van y vuelven, si acepta cargar
 5	 * extensiones— se declara aquí una sola vez, en lugar de en cada consumidor.
 6	 */
 7	import { SQL } from 'bun'
 8	
 9	/**
10	 * Motores admitidos hoy. `sqlite:`/`file:` y `postgres:`/`postgresql:` abren;
11	 * `mysql:`/`mariadb:` están declarados en la URL pero su soporte llega en una
12	 * fase posterior (D7), así que se rechazan nombrándolos en vez de como un
13	 * esquema desconocido.
14	 */
15	export const DIALECTS = ['sqlite', 'postgres'] as const
16	export type Dialect = (typeof DIALECTS)[number]
17	
18	const DECLARED_PENDING = ['mysql', 'mariadb'] as const
19	
20	function schemeOf(url: string): string | undefined {
21	  return /^([a-z][a-z0-9+.-]*):/i.exec(url)?.[1]?.toLowerCase()
22	}
23	
24	/** Enmascara las credenciales de una URL de conexión antes de que viajen a un mensaje. */
25	function maskCredentials(url: string): string {
26	  return url.replace(/\/\/[^@/]*@/, '//***@')
27	}
28	
29	/** El motor que nombra una URL de base de datos, o `null` si no es uno admitido. */
30	export function dialectOf(url: string): Dialect | null {
31	  const scheme = schemeOf(url)
32	  if (scheme === 'sqlite' || scheme === 'file') return 'sqlite'
33	  if (scheme === 'postgres' || scheme === 'postgresql') return 'postgres'
34	  return null
35	}
36	
37	export function jsonParam(dialect: Dialect, value: unknown): unknown {
38	  return dialect === 'postgres' ? value : JSON.stringify(value)
39	}
40	
41	export function readJson(value: unknown): Record<string, unknown> {
42	  return (typeof value === 'string' ? JSON.parse(value) : value) as Record<string, unknown>
43	}
44	
45	export function readTimestamp(value: unknown): string {
46	  return value instanceof Date ? value.toISOString() : String(value)
47	}
48	
49	export function readId(value: unknown): number {
50	  return Number(value)
51	}
52	
53	/** Lo que el motor de una URL permite abrir, más allá de su dialecto. */
54	export type StoreCapabilities = { dialect: Dialect; extensionsLoadable: boolean }
55	
56	/**
57	 * Abre la conexión que la URL declara: motor, dialecto y capacidades, en un
58	 * solo sitio. `sqlite:` no puede cargar extensiones (H-THYROX-238: `Bun.SQL`
59	 * no expone `loadExtension` sobre ese motor, al revés que `bun:sqlite`);
60	 * `postgres:` sí.
61	 */
62	export function openByUrl(url: string): { sql: SQL; dialect: Dialect; capabilities: StoreCapabilities } {
63	  const masked = maskCredentials(url)
64	  const scheme = schemeOf(url)
65	  if (scheme && (DECLARED_PENDING as readonly string[]).includes(scheme)) {
66	    throw new Error(`database URL '${masked}' declares engine '${scheme}', not yet supported (phase D7)`)
67	  }
68	  const dialect = dialectOf(url)
69	  if (!dialect) throw new Error(`unsupported database URL '${masked}': expected sqlite:// or postgres://`)
70	  return { sql: new SQL(url), dialect, capabilities: { dialect, extensionsLoadable: dialect === 'postgres' } }
71	}

